//! Modes `streaming-eval` (probabilistic, H8 P3) and `instance-exact` (per-key exact in d, H8 P4) for ONE stored
//! rule with a stored certificate (cert_rule.frame weights).
//!
//! Port of the H8 kernel's `main()` (handoff/helper-h10-kernel/src/main.rs, its README for record fields, grammar,
//! arithmetic and point derivation). Differences to the standalone kernel, all deliberate:
//! * IBP rows: the caller may pass rows generated by the ENGINE (`EngineRows`, from
//!   `SourceSystem::from_family_with_capacity`, see `engine.rs`); they are compared with the certificate's stored
//!   `source_row` records and the ENGINE rows are the ones used.
//! * Verification primes: candidates `7*2^60 | (w >> 5) | 1`, i.e. in [7*2^60, 7.5*2^60) = [2^62+2^61+2^60, ...),
//!   disjoint from every reconstruction / lift / verify stream of the engine (notes/prime-audit.md: sampled lift and
//!   LiteRed below 2^62, ordered-reduction lift [2^62, 2^62+2^61) and verify [2^62+2^61, 2^62+2^61+2^59),
//!   replay 2^61-1 / 2^61-31, terminal relations from 2^61 upward, gate.py 2^63-25). The range is written into the
//!   record (`prime_range`), and so are the primes.
//! * Verdicts: the probabilistic verdict is `PASS_PROBABILISTIC` (never contains EXACT) with the error bound in the
//!   same record; per-key exact statuses are `EXACT_PROVED_AT_KEY`, and `instance-exact` mode reports
//!   `EXACT_ALL_KEYS_PROVED` only when every key is proved.
//! * Affine cases (rule `equations` non-empty): the case equations are solved over Z for dependent indices with a
//!   unit pivot; random points draw only the independent indices and compute the dependent ones; the degree pass
//!   counts the dependent indices as identity variables, so the total-degree bound D and B_d stay valid after the
//!   affine substitution (substituting degree-1 forms cannot raise a monomial's total degree, nor touch d).
//!   Keys must assign every non-fixed index and satisfy the equations (else `NOT_IN_CASE`).
#![allow(clippy::all)]
use std::collections::HashMap;
use std::time::Instant;

use crate::core::*;

/// Prime window of the verification points (see module doc).
pub const PRIME_BASE: u64 = 7u64 << 60;
pub const PRIME_RANGE_NOTE: &str = "[7*2^60, 7*2^60+2^59): disjoint from the engine's lift/reconstruction/verify streams (notes/prime-audit.md)";
pub fn prime_candidate(w: u64) -> u64 {
    PRIME_BASE | (w >> 5) | 1
}

#[derive(Clone, Debug)]
pub struct StoredArgs {
    pub table: String,
    pub cert: String,
    pub rule: i64,
    pub chart: Option<String>,
    pub kmod: usize,
    pub kex: usize,
    pub factors: Option<String>,
    pub keys: Vec<Vec<(usize, i64)>>,
    pub bd_from: String,
    pub ignore_exc: bool,
    pub xbits: u32,
    pub dden: i64,
    /// "streaming-eval" or "instance-exact"
    pub mode: String,
}
impl Default for StoredArgs {
    fn default() -> Self {
        StoredArgs { table: String::new(), cert: String::new(), rule: -1, chart: None, kmod: 2, kex: 2, factors: None, keys: vec![], bd_from: "best".into(), ignore_exc: false, xbits: 62, dden: 7, mode: "streaming-eval".into() }
    }
}

/// Source rows produced outside the certificate (the engine's generator), in the cert's `source_row` line format.
#[derive(Clone, Debug)]
pub struct EngineRows {
    pub note: String,
    pub lines: Vec<Vec<u8>>,
}

pub type Rows = HashMap<i64, Vec<(Vec<i64>, Aff)>>;
pub fn load_rows(lines: &[Vec<u8>], nonaffine: &mut usize, row_terms: &mut usize) -> Rows {
    let mut rows = HashMap::new();
    for l in lines {
        let j = jparse(l);
        let m = j.get(l, "m").unwrap_or_else(|| die("source_row without m")).int(l);
        let mut v = vec![];
        for t in j.get(l, "terms").unwrap_or_else(|| die("source_row without terms")).arr() {
            let a = t.arr();
            let p = parse_pat(a[0].s(l));
            if p.iter().any(|x| !x.0) {
                die("source row with numeric slot");
            }
            *row_terms += 1;
            match parse_affine(a[1].s(l)) {
                Ok(af) => v.push((p.iter().map(|x| x.1).collect(), af)),
                Err(e) => {
                    *nonaffine += 1;
                    eprintln!("{}", e);
                }
            }
        }
        rows.insert(m, v);
    }
    rows
}
pub fn rows_equal(a: &Rows, b: &Rows) -> bool {
    let norm = |r: &Rows| -> HashMap<i64, Vec<(Vec<i64>, Aff)>> {
        r.iter().map(|(k, v)| { let mut v = v.clone(); v.sort_by(|a, b| a.0.cmp(&b.0)); (*k, v) }).collect()
    };
    let (a, b) = (norm(a), norm(b));
    a.len() == b.len() && a.iter().all(|(k, v)| b.get(k) == Some(v))
}

/// Solve affine case equations over Z: returns (dependent var, affine form in the remaining variables) in an order
/// such that every form only uses independent variables. Refuses non-unit pivots.
pub fn solve_case(eqs: &[Aff], fixed: &[Option<i64>; 20]) -> Result<Vec<(usize, Aff)>, String> {
    // substitute fixed values first
    let subst_fixed = |a: &Aff| -> Aff {
        let mut c0 = a.c0;
        let mut lin = vec![];
        for &(v, c) in &a.lin {
            match fixed.get(v as usize).copied().flatten() {
                Some(x) if (v as usize) < 20 => c0 += c * x,
                _ => lin.push((v, c)),
            }
        }
        Aff { c0, lin }
    };
    let mut pending: Vec<Aff> = eqs.iter().map(subst_fixed).collect();
    let mut solved: Vec<(usize, Aff)> = vec![];
    // substitute var := form into an affine expression
    fn sub(a: &Aff, var: usize, form: &Aff) -> Aff {
        let c = a.lin.iter().find(|x| x.0 as usize == var).map(|x| x.1).unwrap_or(0);
        if c == 0 {
            return a.clone();
        }
        let mut lin: HashMap<u8, i64> = HashMap::new();
        for &(v, k) in &a.lin {
            if v as usize != var {
                *lin.entry(v).or_insert(0) += k;
            }
        }
        for &(v, k) in &form.lin {
            *lin.entry(v).or_insert(0) += c * k;
        }
        let mut l: Vec<(u8, i64)> = lin.into_iter().filter(|x| x.1 != 0).collect();
        l.sort();
        Aff { c0: a.c0 + c * form.c0, lin: l }
    }
    while let Some(pos) = pending.iter().position(|_| true) {
        let e = pending.remove(pos);
        if e.lin.iter().any(|x| x.0 as usize == DV) {
            return Err("case equation involves d".into());
        }
        if e.lin.is_empty() {
            if e.c0 != 0 {
                return Err("inconsistent case equations".into());
            }
            continue;
        }
        // unit pivot, highest index first
        let piv = e.lin.iter().rev().find(|x| x.1 == 1 || x.1 == -1).copied().ok_or_else(|| "UNSUPPORTED: case equation without a unit coefficient (non-unimodular affine case)".to_string())?;
        let var = piv.0 as usize;
        // var = -(e - piv*var)/piv
        let s = -piv.1; // since piv = +-1, 1/piv = piv
        let form = Aff { c0: e.c0 * s, lin: e.lin.iter().filter(|x| x.0 as usize != var).map(|&(v, c)| (v, c * s)).collect() };
        for p in pending.iter_mut() {
            *p = sub(p, var, &form);
        }
        for (_, f) in solved.iter_mut() {
            *f = sub(f, var, &form);
        }
        solved.push((var, form));
    }
    Ok(solved)
}

pub fn run_stored(args: &StoredArgs, engine: Option<&EngineRows>) -> String {
    let t_all = Instant::now();
    let mut o: Vec<(String, String)> = vec![];
    macro_rules! put { ($k:expr, $v:expr) => { o.push(($k.to_string(), $v)) } }
    put!("schema", jstr("rustred.proof-kernel.stored.v1"));
    put!("mode", jstr(&args.mode));

    // ---------------------------------------------------------------- load records
    let t0 = Instant::now();
    let mut tline: Vec<u8> = vec![];
    let mut ln = 0usize;
    read_lines_matching(&args.table, |l| {
        ln += 1;
        if record_kind(l, &args.table, ln, TABLE_KINDS) == Some(b"rule") && top_int(l, "index") == Some(args.rule) {
            let j = jparse(l);
            let ok = j.get(l, "index").map(|x| x.int(l)) == Some(args.rule) && args.chart.as_ref().map_or(true, |c| j.get(l, "chart").unwrap().s(l) == c.as_bytes());
            if ok { tline = l.to_vec(); return false; }
        }
        true
    });
    if tline.is_empty() { die("rule record not found in table"); }
    let tj = jparse(&tline);
    let chart = String::from_utf8(tj.get(&tline, "chart").unwrap().s(&tline).to_vec()).unwrap();
    let mut cline: Vec<u8> = vec![];
    let mut src_lines: Vec<Vec<u8>> = vec![];
    let mut basis: HashMap<i64, Vec<(i64, i64)>> = HashMap::new();
    let mut ln = 0usize;
    read_lines_matching(&args.cert, |l| {
        ln += 1;
        let kind = record_kind(l, &args.cert, ln, CERT_KINDS);
        if kind == Some(b"source_row") { src_lines.push(l.to_vec()); }
        else if kind == Some(b"basis_row") {
            let j = jparse(l);
            if j.get(l, "chart").unwrap().s(l) == chart.as_bytes() {
                let k = j.get(l, "k").unwrap().int(l);
                basis.insert(k, j.get(l, "sources").unwrap().arr().iter().map(|x| { let a = x.arr(); (a[0].int(l), a[1].int(l)) }).collect());
            }
        } else if cline.is_empty() && kind == Some(b"cert_rule") && top_int(l, "rule") == Some(args.rule) {
            let j = jparse(l);
            if j.get(l, "chart").unwrap().s(l) == chart.as_bytes() && j.get(l, "rule").unwrap().int(l) == args.rule { cline = l.to_vec(); }
        }
        true
    });
    if cline.is_empty() { die("MISSING_CERT_RULE: no cert_rule record (stored weights) for this rule; use mode instance-span"); }
    let cj = jparse(&cline);
    let t_load = t0.elapsed().as_secs_f64();

    // ---------------------------------------------------------------- hash seed
    let th = Instant::now();
    let mut base = Sha256::new(); base.update(&tline); base.update(&cline);
    let seed_hex = hex(&base.clone().finish());
    let t_hash = th.elapsed().as_secs_f64();

    // ---------------------------------------------------------------- case (coordinate or affine)
    let (na, fixed) = fixed_slots(&tj, &tline);
    let bounds = domain_bounds(&tj, &tline, na);
    let eq_texts: Vec<&[u8]> = tj.get(&tline, "equations").map(|x| x.arr().iter().map(|e| e.s(&tline)).collect()).unwrap_or_default();
    let eq_aff: Vec<Aff> = eq_texts.iter().map(|s| parse_affine(s).unwrap_or_else(|e| die(&format!("case equation not affine: {}", e)))).collect();
    let dependents = solve_case(&eq_aff, &fixed).unwrap_or_else(|e| die(&e));
    let mut idv = [false; NV]; for i in 0..20 { idv[i] = fixed[i].is_none(); } idv[DV] = true;
    let free: Vec<usize> = (0..NV).filter(|&v| idv[v]).collect();
    let draw: Vec<usize> = free.iter().copied().filter(|v| !dependents.iter().any(|d| d.0 == *v)).collect();
    let vname = |v: usize| if v == DV { "d".to_string() } else { format!("n{}", v) };
    put!("rule", format!("{}", args.rule)); put!("chart", jstr(&chart)); put!("arity", format!("{}", na));
    put!("free_vars", format!("[{}]", free.iter().map(|&v| jstr(&vname(v))).collect::<Vec<_>>().join(",")));
    if !dependents.is_empty() {
        put!("affine_case", format!("{{\"equations\":{},\"dependent\":[{}],\"drawn_vars\":[{}]}}", eq_texts.len(),
            dependents.iter().map(|(v, f)| format!("{{\"var\":{},\"c0\":{},\"lin\":[{}]}}", jstr(&vname(*v)), f.c0, f.lin.iter().map(|(x, c)| format!("[{},{}]", jstr(&vname(*x as usize)), c)).collect::<Vec<_>>().join(","))).collect::<Vec<_>>().join(","),
            draw.iter().map(|&v| jstr(&vname(v))).collect::<Vec<_>>().join(",")));
    }
    put!("seed_sha256_T_C", jstr(&seed_hex));
    let rec_sha = record_sha256(&tline);
    put!("record_sha256", jstr(&rec_sha));
    put!("record_bytes", format!("{{\"table\":{},\"cert\":{}}}", tline.len(), cline.len()));

    // ---------------------------------------------------------------- source rows: engine (preferred) vs cert
    let mut nonaffine = 0usize; let mut row_terms = 0usize;
    let cert_rows = load_rows(&src_lines, &mut nonaffine, &mut row_terms);
    let rows: Rows;
    let rows_note;
    if let Some(er) = engine {
        let (mut na2, mut rt2) = (0, 0);
        let exr = load_rows(&er.lines, &mut na2, &mut rt2);
        nonaffine += na2;
        let same = rows_equal(&cert_rows, &exr);
        rows_note = format!("{{\"source\":\"engine\",\"engine\":{},\"engine_rows\":{},\"cert_rows\":{},\"equal_to_cert_source_rows\":{}}}", jstr(&er.note), exr.len(), cert_rows.len(), same);
        rows = exr;
    } else {
        rows_note = format!("{{\"source\":\"cert source_row records\",\"cert_rows\":{}}}", cert_rows.len());
        rows = cert_rows;
    }
    put!("rows", rows_note);
    put!("row_terms", format!("{{\"terms\":{},\"non_affine\":{}}}", row_terms, nonaffine));
    if nonaffine > 0 { die("a row coefficient is not affine (see stderr)"); }

    // ---------------------------------------------------------------- columns, a_{j,c}
    let frame = cj.get(&cline, "frame").unwrap().arr();
    let mut colid: HashMap<Pat, u32> = HashMap::new(); let mut colpat: Vec<Pat> = vec![];
    let cid = |p: Pat, colid: &mut HashMap<Pat, u32>, colpat: &mut Vec<Pat>| -> u32 { if let Some(&i) = colid.get(&p) { i } else { let i = colpat.len() as u32; colid.insert(p.clone(), i); colpat.push(p); i } };
    let mut wcols: Vec<Vec<(u32, Aff)>> = vec![]; let mut wtext: Vec<&[u8]> = vec![];
    for fr in frame {
        let a = fr.arr(); let k = a[0].int(&cline); let at = parse_pat(a[1].s(&cline)); wtext.push(a[2].s(&cline));
        let brow = basis.get(&k).unwrap_or_else(|| die("basis row missing"));
        let mut acc: HashMap<Pat, (i64, [i64; NV])> = HashMap::new();
        for &(m, pkm) in brow {
            for (off, af) in rows.get(&m).unwrap_or_else(|| die("source row missing")) {
                let col: Pat = at.iter().zip(off).map(|(&(s, o), &t)| (s, o + t)).collect();
                let e = acc.entry(col).or_insert((0, [0; NV]));
                e.0 += pkm * af.c0;
                for &(v, c) in &af.lin {
                    let v = v as usize;
                    if v == DV { e.1[DV] += pkm * c; }
                    else { let (s, o) = at[v]; if s { e.1[v] += pkm * c; e.0 += pkm * c * o; } else { e.0 += pkm * c * o; } }
                }
            }
        }
        let mut lst = vec![];
        let mut keys: Vec<_> = acc.into_iter().collect(); keys.sort_by(|a, b| a.0.cmp(&b.0));
        for (col, (c0, lin)) in keys {
            let lin: Vec<(u8, i64)> = (0..NV).filter(|&v| lin[v] != 0).map(|v| (v as u8, lin[v])).collect();
            if c0 != 0 || !lin.is_empty() { let id = cid(col, &mut colid, &mut colpat); lst.push((id, Aff { c0, lin })); }
        }
        wcols.push(lst);
    }
    let rhs_arr = tj.get(&tline, "rhs").unwrap().arr();
    let rhs: Vec<(u32, &[u8])> = rhs_arr.iter().map(|x| { let a = x.arr(); (cid(parse_pat(a[0].s(&tline)), &mut colid, &mut colpat), a[1].s(&tline)) }).collect();
    let tgt = cid(parse_pat(tj.get(&tline, "target").unwrap().s(&tline)), &mut colid, &mut colpat);
    let ncol = colpat.len();
    let a_maxvars = wcols.iter().flat_map(|l| l.iter().map(|(_, a)| a.lin.iter().filter(|x| idv[x.0 as usize]).count())).max().unwrap_or(0);
    put!("sizes", format!("{{\"weights\":{},\"rhs_terms\":{},\"columns\":{},\"a_entries\":{},\"a_max_vars\":{},\"a_max_total_degree\":1}}", frame.len(), rhs.len(), ncol, wcols.iter().map(|x| x.len()).sum::<usize>(), a_maxvars));

    // ---------------------------------------------------------------- pass 0: degrees (text only)
    let tdp = Instant::now();
    let mut dentext: HashMap<&[u8], usize> = HashMap::new(); let mut dens: Vec<&[u8]> = vec![];
    let one: &[u8] = b"1";
    let mut den_of = |s: Option<&[u8]>, dentext: &mut HashMap<&[u8], usize>, dens: &mut Vec<&[u8]>| -> usize {
        let s = s.unwrap_or(one);
        // SAFETY of lifetimes: all texts live in tline/cline which outlive this function body
        let s: &[u8] = unsafe { std::mem::transmute::<&[u8], &'static [u8]>(s) };
        if let Some(&i) = dentext.get(s) { i } else { let i = dens.len(); dentext.insert(s, i); dens.push(s); i }
    };
    let mut wnum: Vec<&[u8]> = vec![]; let mut wden: Vec<usize> = vec![]; let mut wdeg: Vec<Deg> = vec![];
    let mut nmono_num = 0u64; let mut maxbits = 0u32; let mut text_bytes = 0usize;
    for s in &wtext { let (n, d) = split_coef(s); text_bytes += s.len(); let dg = text_deg(n, &idv); nmono_num += dg.nmono; maxbits = maxbits.max(dg.maxcoefbits); wnum.push(n); wdeg.push(dg); wden.push(den_of(d, &mut dentext, &mut dens)); }
    let mut rnum: Vec<&[u8]> = vec![]; let mut rden: Vec<usize> = vec![]; let mut rdeg: Vec<Deg> = vec![];
    for (_, s) in &rhs { let (n, d) = split_coef(s); text_bytes += s.len(); let dg = text_deg(n, &idv); nmono_num += dg.nmono; maxbits = maxbits.max(dg.maxcoefbits); rnum.push(n); rdeg.push(dg); rden.push(den_of(d, &mut dentext, &mut dens)); }
    let ddeg: Vec<Deg> = dens.iter().map(|s| text_deg(s, &idv)).collect();
    let nmono_den_texts: u64 = wden.iter().chain(rden.iter()).map(|&i| ddeg[i].nmono).sum();
    let mut maxe = [0u32; NV];
    for d in wdeg.iter().chain(rdeg.iter()).chain(ddeg.iter()) { for v in 0..NV { maxe[v] = maxe[v].max(d.v[v]); } }
    let gdeg = maxe[DV];
    let dpoly: Vec<Poly> = dens.iter().map(|s| poly_parse(s)).collect();
    let mut cls: HashMap<Poly, usize> = HashMap::new(); let mut dcls: Vec<usize> = vec![]; let mut clsrep: Vec<usize> = vec![];
    for (i, p) in dpoly.iter().enumerate() { if p.is_empty() { die("a denominator text is identically zero"); } let n = poly_normal(p); let l = cls.len(); let c = *cls.entry(n).or_insert(l); if c == clsrep.len() { clsrep.push(i); } dcls.push(c); }
    let t_deg = tdp.elapsed().as_secs_f64();
    let fv = |d: &[u32; NV]| -> String { format!("{{{}}}", free.iter().map(|&v| format!("{}:{}", jstr(&vname(v)), d[v])).collect::<Vec<_>>().join(",")) };
    let mut ndmax = [0u32; NV]; let mut ndtot = 0;
    for d in wdeg.iter().chain(rdeg.iter()) { for v in 0..NV { ndmax[v] = ndmax[v].max(d.v[v]); } ndtot = ndtot.max(d.tot); }
    put!("monomials", format!("{{\"numerators\":{},\"denominators_as_written\":{},\"total\":{},\"text_bytes\":{},\"max_coef_bits\":{}}}", nmono_num, nmono_den_texts, nmono_num + nmono_den_texts, text_bytes, maxbits));
    put!("numerator_degree_max", format!("{{\"deg\":{},\"total\":{}}}", fv(&ndmax), ndtot));
    put!("denominators", format!("{{\"distinct_texts\":{},\"distinct_up_to_constant\":{},\"homogenising_deg_d_G\":{}}}", dens.len(), clsrep.len(), gdeg));

    // ---------------------------------------------------------------- K4 bounds
    let cof_prod: Vec<([u32; NV], u32)> = (0..dens.len()).map(|i| {
        let mut v = [0u32; NV]; let mut t = 0;
        for (c, &r) in clsrep.iter().enumerate() { if c != dcls[i] { for x in 0..NV { v[x] += ddeg[r].v[x]; } t += ddeg[r].tot; } }
        (v, t)
    }).collect();
    let qprod: ([u32; NV], u32) = { let mut v = [0u32; NV]; let mut t = 0; for &r in &clsrep { for x in 0..NV { v[x] += ddeg[r].v[x]; } t += ddeg[r].tot; } (v, t) };
    let bound = |cof: &Vec<([u32; NV], u32)>, q: &([u32; NV], u32)| -> ([u32; NV], u32) {
        let mut b = q.0; let mut bt = q.1;
        for j in 0..wcols.len() {
            let (cv, ct) = &cof[wden[j]];
            for (_, a) in &wcols[j] {
                let mut any = false;
                for &x in &free { let inx = a.lin.iter().any(|y| y.0 as usize == x); if inx { any = true; } b[x] = b[x].max(cv[x] + wdeg[j].v[x] + inx as u32); }
                bt = bt.max(ct + wdeg[j].tot + any as u32);
            }
        }
        for i in 0..rhs.len() { let (cv, ct) = &cof[rden[i]]; for &x in &free { b[x] = b[x].max(cv[x] + rdeg[i].v[x]); } bt = bt.max(ct + rdeg[i].tot); }
        (b, bt)
    };
    let (bp, bpt) = bound(&cof_prod, &qprod);
    put!("Q_product_of_distinct", format!("{{\"deg\":{},\"total\":{}}}", fv(&qprod.0), qprod.1));
    put!("bound_P_with_Q_product", format!("{{\"deg\":{},\"total\":{}}}", fv(&bp), bpt));
    let mut blcm: Option<([u32; NV], u32)> = None;
    if let Some(ff) = &args.factors {
        let mut fl = vec![]; read_lines_matching(ff, |l| { if find(&l[..l.len().min(64)], b"\"den_factors\"") { fl = l.to_vec(); false } else { true } });
        if fl.is_empty() { die("no den_factors record"); }
        let fj = jparse(&fl);
        let fac: Vec<&[u8]> = fj.get(&fl, "factors").unwrap().arr().iter().map(|x| x.s(&fl)).collect();
        let fpoly: Vec<Poly> = fac.iter().map(|s| poly_parse(s)).collect();
        let fdeg: Vec<Deg> = fac.iter().map(|s| text_deg(s, &idv)).collect();
        let mut expof: HashMap<Vec<u8>, Vec<u32>> = HashMap::new(); let mut verified = 0; let mut bad = 0;
        for d in fj.get(&fl, "dens").unwrap().arr() {
            let txt = d.get(&fl, "den").unwrap().s(&fl).to_vec(); let unit = d.get(&fl, "unit").unwrap().int(&fl) as i128;
            let ex: Vec<u32> = d.get(&fl, "exp").unwrap().arr().iter().map(|x| x.int(&fl) as u32).collect();
            if ex.len() != fac.len() { die("den_factors: exponent vector length"); }
            let mut p: Poly = vec![(0, unit)];
            for (i, &e) in ex.iter().enumerate() { for _ in 0..e { p = poly_mul(&p, &fpoly[i]); } }
            let tp = poly_parse(&txt);
            if tp == p { verified += 1; } else { bad += 1; eprintln!("den_factors: claimed factorisation of {} is WRONG", String::from_utf8_lossy(&txt)); }
            expof.insert(txt, ex);
        }
        let missing = dens.iter().filter(|s| **s != b"1" && !expof.contains_key(**s)).count();
        if bad > 0 || missing > 0 { put!("lcm", format!("{{\"error\":\"factorisation wrong ({}) or missing ({})\"}}", bad, missing)); }
        else {
            let mut mx = vec![0u32; fac.len()];
            for s in &dens { if let Some(e) = expof.get(*s) { for i in 0..fac.len() { mx[i] = mx[i].max(e[i]); } } }
            let qv = { let mut v = [0u32; NV]; let mut t = 0; for i in 0..fac.len() { for x in 0..NV { v[x] += mx[i] * fdeg[i].v[x]; } t += mx[i] * fdeg[i].tot; } (v, t) };
            let cof_l: Vec<([u32; NV], u32)> = dens.iter().map(|s| {
                let e = expof.get(*s).cloned().unwrap_or(vec![0; fac.len()]);
                let mut v = [0u32; NV]; let mut t = 0; for i in 0..fac.len() { for x in 0..NV { v[x] += (mx[i] - e[i]) * fdeg[i].v[x]; } t += (mx[i] - e[i]) * fdeg[i].tot; } (v, t)
            }).collect();
            let bl = bound(&cof_l, &qv);
            put!("Q_lcm_from_stored_factors", format!("{{\"factors\":{},\"verified_dens\":{},\"deg\":{},\"total\":{}}}", fac.len(), verified, fv(&qv.0), qv.1));
            put!("bound_P_with_Q_lcm", format!("{{\"deg\":{},\"total\":{}}}", fv(&bl.0), bl.1));
            blcm = Some(bl);
        }
    }
    let (bsel, bsel_t, bsel_name) = match (&blcm, args.bd_from.as_str()) { (Some(b), "lcm") | (Some(b), "best") => (b.0, b.1, "lcm"), _ => (bp, bpt, "product") };
    let dtot = bsel_t as f64;
    put!("degree_pass_s", format!("{:.3}", t_deg));

    // ---------------------------------------------------------------- denominators at a candidate point; pole test
    let eval_dens = |pts: &[Point], scratch: &mut (Vec<u64>, Vec<u64>)| -> Vec<Vec<Val>> {
        let mut out = vec![]; let mut tmp = vec![]; let mut nm = 0;
        for s in &dens { eval_sum(s, pts, &mut tmp, scratch, &mut nm); out.push(tmp.clone()); }
        out
    };
    let is_zero = |v: &Val| match v { Val::M(x) => *x == 0, Val::E(b) => b.is_zero() };
    let mut scratch = (Vec::new(), Vec::new());
    let mut stream = Stream::new(base.clone());
    let mk_point = |kind: PKind, label: String| -> Point { Point { kind, mv: [0; NV], ev: vec![Big::zero(); NV], dden: Big::one(), label, pw: vec![], epw: vec![], dden_is_one: true } };
    let set_fixed = |p: &mut Point| { for i in 0..20 { if let Some(x) = fixed[i] { match p.kind { PKind::Mod(m) => p.mv[i] = (x.rem_euclid(m.p as i64)) as u64, PKind::Ex => p.ev[i] = Big::from_i128(x as i128) } } } };
    // dependent indices of an affine case: value = c0 + sum c_v x_v over drawn variables
    let set_dependents = |p: &mut Point| {
        for (var, f) in &dependents {
            match p.kind {
                PKind::Mod(m) => {
                    let mut s = (f.c0.rem_euclid(m.p as i64)) as u64;
                    for &(v, c) in &f.lin { let t = ((c.rem_euclid(m.p as i64)) as u128 * p.mv[v as usize] as u128 % m.p as u128) as u64; s = ((s as u128 + t as u128) % m.p as u128) as u64; }
                    p.mv[*var] = s;
                }
                PKind::Ex => { let mut s = Big::from_i128(f.c0 as i128); for &(v, c) in &f.lin { s.add(&p.ev[v as usize].mul_i64(c)); } p.ev[*var] = s; }
            }
        }
    };

    // ---------------------------------------------------------------- K3: points from the hash stream
    let mut resample_log: Vec<String> = vec![];
    let mut primes: Vec<u64> = vec![];
    while primes.len() < args.kmod { let w = stream.next(); let c = prime_candidate(w); if is_prime(c) && !primes.contains(&c) { primes.push(c); } }
    let mut rpts: Vec<Point> = vec![];
    let mut stuck = false;
    for i in 0..args.kmod + args.kex {
        let mut attempt = 0;
        loop {
            let mut p = if i < args.kmod { mk_point(PKind::Mod(Mont::new(primes[i])), format!("mod{}", i)) } else { mk_point(PKind::Ex, format!("exact{}", i - args.kmod)) };
            for &v in &draw {
                match p.kind {
                    PKind::Mod(m) => { loop { let w = stream.next() >> 1; if w < m.p { p.mv[v] = w; break; } } }
                    PKind::Ex => { p.ev[v] = Big::from_i128(((stream.next() >> (64 - args.xbits)) + 1) as i128); }
                }
            }
            set_fixed(&mut p); set_dependents(&mut p); build_tables(&mut p, &maxe, gdeg);
            let dv = eval_dens(std::slice::from_ref(&p), &mut scratch);
            let poles: Vec<usize> = (0..dens.len()).filter(|&k| is_zero(&dv[k][0])).collect();
            if poles.is_empty() { rpts.push(p); break; }
            attempt += 1;
            resample_log.push(format!("{{\"point\":{},\"attempt\":{},\"vanishing_denominator_ids\":{:?},\"stream_words_drawn\":{}}}", jstr(&p.label), attempt, poles, stream.drawn));
            if attempt >= 64 { stuck = true; break; }
        }
        if stuck { break; }
    }
    if stuck { put!("resamples", format!("[{}]", resample_log.join(","))); put!("verdict", jstr("POLE-STUCK")); return emit(&o); }
    put!("prime_range", jstr(PRIME_RANGE_NOTE));
    put!("primes", format!("[{}]", primes.iter().map(|p| format!("\"{}\"", p)).collect::<Vec<_>>().join(",")));
    put!("points", format!("[{}]", rpts.iter().map(|p| format!("{{\"label\":{},\"values\":{{{}}}}}", jstr(&p.label), free.iter().map(|&v| format!("{}:\"{}\"", jstr(&vname(v)), match p.kind { PKind::Mod(_) => p.mv[v].to_string(), PKind::Ex => p.ev[v].to_dec() })).collect::<Vec<_>>().join(","))).collect::<Vec<_>>().join(",")));
    put!("resamples", format!("[{}]", resample_log.join(",")));
    put!("stream_words_drawn", format!("{}", stream.drawn));

    // ---------------------------------------------------------------- K2: the streaming pass
    let run_pass = |pts: &mut Vec<Point>, scratch: &mut (Vec<u64>, Vec<u64>)| -> (Vec<(usize, Option<u32>, u64)>, f64, u64) {
        let tp = Instant::now();
        let np = pts.len();
        let dv = eval_dens(pts, scratch);
        let mut dinv: Vec<Vec<u64>> = vec![vec![0; np]; dens.len()];
        let mut cof: Vec<Vec<Big>> = vec![vec![Big::zero(); np]; dens.len()];
        let mut lam: Vec<Big> = vec![Big::zero(); np];
        for pi in 0..np {
            match pts[pi].kind {
                PKind::Mod(m) => { for k in 0..dens.len() { if let Val::M(x) = dv[k][pi] { dinv[k][pi] = m.inv(x); } } }
                PKind::Ex => {
                    let mut cl: Vec<Vec<u64>> = vec![]; let mut kc = vec![0usize; dens.len()];
                    for k in 0..dens.len() { if let Val::E(b) = &dv[k][pi] { match cl.iter().position(|c| *c == b.m) { Some(i) => kc[k] = i, None => { kc[k] = cl.len(); cl.push(b.m.clone()); } } } }
                    let n = cl.len(); let mut pre = vec![Big::one(); n + 1]; let mut suf = vec![Big::one(); n + 1];
                    for i in 0..n { pre[i + 1] = pre[i].mul(&Big { neg: false, m: cl[i].clone() }); }
                    for i in (0..n).rev() { suf[i] = suf[i + 1].mul(&Big { neg: false, m: cl[i].clone() }); }
                    for k in 0..dens.len() { let mut c = pre[kc[k]].mul(&suf[kc[k] + 1]); if let Val::E(b) = &dv[k][pi] { c.neg = b.neg && !c.is_zero(); } cof[k][pi] = c; }
                    lam[pi] = pre[n].mul(&pts[pi].dden);
                }
            }
        }
        let mut accm: Vec<u64> = vec![0; ncol * np]; let mut acce: Vec<Big> = if pts.iter().any(|p| matches!(p.kind, PKind::Ex)) { vec![Big::zero(); ncol * np] } else { vec![] };
        let mut vals = vec![]; let mut nmono = 0u64;
        let aff_mod = |a: &Aff, p: &Point, m: &Mont| -> u64 { let mut s = m.from_i64(a.c0); for &(v, c) in &a.lin { s = m.add(s, m.mul(m.from_i64(c), m.to(p.mv[v as usize]))); } s };
        let aff_ex = |a: &Aff, p: &Point| -> Big { let mut s = Big::from_i128(a.c0 as i128).mul(&p.dden); let mut sd = Big::zero(); for &(v, c) in &a.lin { let t = Big::from_i128(c as i128).mul(&p.ev[v as usize]); if v as usize == DV { sd.add(&t); } else { s.add(&t.mul(&p.dden)); } } s.add(&sd); s };
        for j in 0..wnum.len() {
            eval_sum(wnum[j], pts, &mut vals, scratch, &mut nmono);
            for pi in 0..np {
                let p = &pts[pi];
                match (&p.kind, &vals[pi]) {
                    (PKind::Mod(m), Val::M(x)) => { let w = m.mul(*x, dinv[wden[j]][pi]); for (c, a) in &wcols[j] { let i = *c as usize * np + pi; accm[i] = m.add(accm[i], m.mul(w, aff_mod(a, p, m))); } }
                    (PKind::Ex, Val::E(x)) => { if x.is_zero() { continue; } let y = x.mul(&cof[wden[j]][pi]); for (c, a) in &wcols[j] { let t = y.mul(&aff_ex(a, p)); acce[*c as usize * np + pi].add(&t); } }
                    _ => unreachable!(),
                }
            }
        }
        for i in 0..rnum.len() {
            eval_sum(rnum[i], pts, &mut vals, scratch, &mut nmono);
            let c = rhs[i].0 as usize;
            for pi in 0..np {
                let p = &pts[pi];
                match (&p.kind, &vals[pi]) {
                    (PKind::Mod(m), Val::M(x)) => { let k = c * np + pi; accm[k] = m.add(accm[k], m.mul(*x, dinv[rden[i]][pi])); }
                    (PKind::Ex, Val::E(x)) => { let t = x.mul(&cof[rden[i]][pi]).mul(&p.dden); acce[c * np + pi].add(&t); }
                    _ => unreachable!(),
                }
            }
        }
        for pi in 0..np {
            let k = tgt as usize * np + pi;
            match &pts[pi].kind { PKind::Mod(m) => accm[k] = m.sub(accm[k], m.to(1)), PKind::Ex => { let mut l = lam[pi].clone(); l.neg = !l.neg; acce[k].add(&l); } }
        }
        let mut res = vec![];
        for pi in 0..np {
            let mut nz = 0; let mut first = None; let mut bits = 0;
            for c in 0..ncol {
                let z = match pts[pi].kind { PKind::Mod(_) => accm[c * np + pi] == 0, PKind::Ex => { bits = bits.max(acce[c * np + pi].bits()); acce[c * np + pi].is_zero() } };
                if !z { nz += 1; if first.is_none() { first = Some(c as u32); } }
            }
            if let PKind::Ex = pts[pi].kind { bits = bits.max(lam[pi].bits()); }
            res.push((nz, first, bits));
        }
        (res, tp.elapsed().as_secs_f64(), nmono)
    };

    let mut verdict_fail = false;
    let mut pass_json = vec![];
    let modpts: Vec<Point> = rpts.iter().filter(|p| matches!(p.kind, PKind::Mod(_))).cloned().collect();
    let expts: Vec<Point> = rpts.iter().filter(|p| matches!(p.kind, PKind::Ex)).cloned().collect();
    for (name, mut pts) in [("mod_p", modpts), ("exact_Z", expts)] {
        if pts.is_empty() { continue; }
        let (res, secs, nm) = run_pass(&mut pts, &mut scratch);
        let mut pj = vec![];
        for (p, (nz, first, bits)) in pts.iter().zip(res.iter()) {
            if *nz > 0 { verdict_fail = true; }
            pj.push(format!("{{\"label\":{},\"nonzero_columns\":{},\"first_nonzero_column\":{},\"max_accumulator_bits\":{}}}", jstr(&p.label), nz, first.map(|c| jstr(&pat_str(&colpat[c as usize]))).unwrap_or("null".into()), bits));
        }
        pass_json.push(format!("{{\"arithmetic\":\"{}\",\"points\":{},\"seconds\":{:.4},\"seconds_per_point\":{:.4},\"monomials_streamed\":{},\"ns_per_monomial_per_point\":{:.1},\"residues\":[{}]}}",
            name, pts.len(), secs, secs / pts.len() as f64, nm, secs * 1e9 / (nm as f64 * pts.len() as f64), pj.join(",")));
    }
    put!("evaluation_passes", format!("[{}]", pass_json.join(",")));
    let lg = |k: usize, s: f64| if k == 0 { 0.0 } else { (k as f64) * (dtot / s).log10() };
    // mod-p points: uniform in [0, p) with p >= 7*2^60 > 2^62
    let log_bound = lg(args.kex, 2f64.powi(args.xbits as i32)) + lg(args.kmod, 2f64.powi(62));
    put!("error_bound", format!("{{\"D_used\":{},\"D_from\":\"{}\",\"exact_range\":\"[1,2^{}]\",\"log10_exact_Z_(D/2^bits)^k\":{:.2},\"log10_mod_p_(D/2^62)^k\":{:.2},\"log10_combined\":{:.2},\"note\":\"Schwartz-Zippel on every column polynomial P_c (total degree <= D) at hash-derived points; mod-p term excludes Pr[p divides every coefficient of a nonzero P_c] (H8 P3); exact term has no such caveat; a FAIL is a certain disproof\"}}",
        bsel_t, bsel_name, args.xbits, lg(args.kex, 2f64.powi(args.xbits as i32)), lg(args.kmod, 2f64.powi(62)), log_bound));

    // ---------------------------------------------------------------- K5: per-instance exact proof in d
    let bd = bsel[DV];
    let exc: Vec<Vec<&[u8]>> = tj.get(&tline, "exceptions").map(|e| e.arr().iter().map(|b| b.arr().iter().map(|x| x.s(&tline)).collect()).collect()).unwrap_or_default();
    if exc.iter().any(|b| b.is_empty()) { die("UNSUPPORTED: EMPTY_EXCEPTION_BRANCH (an exception AND-list is empty; the engine never writes one (solver/exception.rs) and refuses it in replay (node/replay/mod.rs:823); read logically it excludes the rule everywhere, as rr_node reduce (node/mastermap.rs:456) and cover (node/driver.rs:1527) treat it)"); }
    let weight_den: Vec<bool> = (0..dens.len()).map(|k| wden.contains(&k)).collect();
    let mut inst_json = vec![]; let mut inst_fail = 0; let mut inst_proved = 0; let mut inst_other = 0;
    for key in &args.keys {
        let tk = Instant::now();
        let mut kv: [Option<i64>; 20] = fixed;
        for &(i, x) in key { if i >= na { die("key slot beyond the rule's arity"); } if fixed[i].is_some() { die("key sets a fixed slot"); } kv[i] = Some(x); }
        if (0..20).any(|i| kv[i].is_none()) { die("key does not assign every free index"); }
        let keystr = key.iter().map(|(i, x)| format!("\"n{}\":{}", i, x)).collect::<Vec<_>>().join(",");
        // affine case: equations must hold at the key
        let in_case = eq_aff.iter().all(|e| e.lin.iter().fold(e.c0, |s, &(v, c)| s + c * kv[v as usize].unwrap_or(0)) == 0)
            && in_bounds(&bounds, |i| kv[i].unwrap_or(0));
        if !in_case { inst_other += 1; inst_json.push(format!("{{\"key\":{{{}}},\"status\":\"NOT_IN_CASE\"}}", keystr)); continue; }
        {
            // chart guards on the target at the key (the rule is used only inside its chart)
            let tp = parse_pat(tj.get(&tline, "target").unwrap().s(&tline));
            let cb = chart.as_bytes();
            let ok = (0..na).all(|i| { let x = if tp[i].0 { kv[i].unwrap() + tp[i].1 } else { tp[i].1 }; if cb[i] == b'1' { x >= 1 } else { x <= 0 } });
            if !ok { inst_other += 1; inst_json.push(format!("{{\"key\":{{{}}},\"status\":\"NOT_IN_CHART (target at the key violates the chart guards)\"}}", keystr)); continue; }
        }
        let mut kp = mk_point(PKind::Ex, "key".into()); for i in 0..20 { kp.ev[i] = Big::from_i128(kv[i].unwrap() as i128); } kp.ev[DV] = Big::zero();
        let mut emaxe = [0u32; NV]; for b in &exc { for s in b { let d = text_deg(s, &idv); for v in 0..NV { emaxe[v] = emaxe[v].max(d.v[v]); } } }
        build_tables(&mut kp, &emaxe, 0);
        let mut on_exc = false;
        for b in &exc { let mut all0 = true; for s in b { let mut t = vec![]; let mut nm = 0; eval_sum(s, std::slice::from_ref(&kp), &mut t, &mut scratch, &mut nm); if !is_zero(&t[0]) { all0 = false; } } if all0 && !b.is_empty() { on_exc = true; } }
        if on_exc && !args.ignore_exc { inst_other += 1; inst_json.push(format!("{{\"key\":{{{}}},\"status\":\"ON_EXCEPTION_BRANCH (not covered by this rule)\"}}", keystr)); continue; }
        let mut zeros = vec![0u32; dens.len()]; let mut pts: Vec<Point> = vec![]; let mut skipped: Vec<String> = vec![]; let mut status = String::new();
        let mut i = 0i64;
        while pts.len() < bd as usize + 1 {
            i += 1;
            let mut p = mk_point(PKind::Ex, format!("d={}/{}", 2 * i + 1, args.dden));
            for v in 0..20 { p.ev[v] = Big::from_i128(kv[v].unwrap() as i128); }
            p.ev[DV] = Big::from_i128((2 * i + 1) as i128); p.dden = Big::from_i128(args.dden as i128);
            build_tables(&mut p, &maxe, gdeg);
            let dvv = eval_dens(std::slice::from_ref(&p), &mut scratch);
            let poles: Vec<usize> = (0..dens.len()).filter(|&k| is_zero(&dvv[k][0])).collect();
            if poles.is_empty() { pts.push(p); continue; }
            skipped.push(format!("\"{}/{}\"", 2 * i + 1, args.dden));
            for &k in &poles {
                zeros[k] += 1;
                if zeros[k] > ddeg[k].v[DV] {
                    status = if weight_den[k] { format!("HIDDEN_KEY (weight denominator id {} vanishes identically in d)", k) } else { format!("IRREGULAR_KEY (rhs denominator id {} vanishes identically in d)", k) };
                }
            }
            if !status.is_empty() { break; }
        }
        if !status.is_empty() { inst_other += 1; inst_json.push(format!("{{\"key\":{{{}}},\"status\":{},\"skipped_pole_d\":[{}]}}", keystr, jstr(&status), skipped.join(","))); continue; }
        let (res, secs, _) = run_pass(&mut pts, &mut scratch);
        let hits: usize = res.iter().filter(|r| r.0 > 0).count();
        let first = res.iter().find_map(|r| r.1).map(|c| jstr(&pat_str(&colpat[c as usize]))).unwrap_or("null".into());
        let proved = hits == 0;
        if proved { inst_proved += 1; } else { inst_fail += 1; }
        inst_json.push(format!("{{\"key\":{{{}}},\"Bd\":{},\"d_points\":{},\"skipped_pole_d\":[{}],\"points_with_nonzero_column\":{},\"first_nonzero_column\":{},\"status\":\"{}\",\"pass_seconds\":{:.3},\"seconds\":{:.3}}}",
            keystr, bd, pts.len(), skipped.join(","), hits, first, if proved { "EXACT_PROVED_AT_KEY" } else { "FAIL_AT_KEY" }, secs, tk.elapsed().as_secs_f64()));
    }
    let echo = format!("\"rule\":{},\"record_sha256\":{},", args.rule, jstr(&rec_sha));
    let inst_json: Vec<String> = inst_json.iter().map(|s| format!("{{{}{}", echo, &s[1..])).collect();
    if !args.keys.is_empty() {
        put!("per_instance", format!("{{\"Bd\":{},\"Bd_from\":\"{}\",\"d_values\":\"(2i+1)/{} for i=1,2,..., poles replaced\",\"statement\":\"at each PROVED key k (all indices integer), every column identity sum_j w_j a_jc + r_c - delta_c = 0 holds identically in d: B_d+1 exact evaluations of a polynomial of d-degree <= B_d (cleared by Q)\",\"keys\":[{}]}}", bd, bsel_name, args.dden, inst_json.join(",")));
        let iv = if inst_fail > 0 { "FAIL".to_string() } else if inst_other == 0 { "EXACT_ALL_KEYS_PROVED".to_string() } else { format!("EXACT_KEYS_PROVED_PARTIAL ({} proved, {} not proved: hidden/irregular/exception/not-in-case)", inst_proved, inst_other) };
        put!("instance_verdict", jstr(&iv));
    }
    let nres = resample_log.len();
    let verdict = if args.mode == "instance-exact" {
        if args.keys.is_empty() { die("instance-exact needs at least one --key"); }
        if verdict_fail || inst_fail > 0 { "FAIL".to_string() } else if inst_other == 0 { "EXACT_ALL_KEYS_PROVED".to_string() } else { "EXACT_KEYS_PROVED_PARTIAL".to_string() }
    } else if verdict_fail { "FAIL".to_string() } else if nres > 0 { format!("PASS_PROBABILISTIC (POLE-RESAMPLED {} times)", nres) } else { "PASS_PROBABILISTIC".to_string() };
    put!("verdict", jstr(&verdict));
    if args.mode != "instance-exact" { put!("verdict_error_bound_log10", format!("{:.2}", log_bound)); }
    put!("timings_s", format!("{{\"load\":{:.3},\"hash\":{:.3},\"degree_pass\":{:.3},\"total\":{:.3}}}", t_load, t_hash, t_deg, t_all.elapsed().as_secs_f64()));
    put!("peak_rss_mb", format!("{:.1}", peak_mb()));
    emit(&o)
}
pub fn emit(o: &Vec<(String, String)>) -> String {
    format!("{{{}}}", o.iter().map(|(k, v)| format!("{}:{}", jstr(k), v)).collect::<Vec<_>>().join(","))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn affine_case_solved_with_unit_pivots_and_refused_otherwise() {
        let fixed: [Option<i64>; 20] = std::array::from_fn(|i| if i == 4 { Some(1) } else { None });
        // n7 = n11 - n10 + 2 ; n1 = n9 + 2 n8 - n6 + n5 + n2 - 1 + n4 (n4 fixed to 1)
        let e1 = parse_affine(b"-2-n11+n10+n7").unwrap();
        let e2 = parse_affine(b"1-n9-2*n8+n6-n5-n2+n1-n4").unwrap();
        let s = solve_case(&[e1.clone(), e2.clone()], &fixed).unwrap();
        assert_eq!(s.len(), 2);
        // every solved form uses only independent variables, and the equations hold at a random point
        let deps: Vec<usize> = s.iter().map(|x| x.0).collect();
        for (_, f) in &s { assert!(f.lin.iter().all(|(v, _)| !deps.contains(&(*v as usize)))); }
        let mut kv = [0i64; 21];
        for (i, x) in kv.iter_mut().enumerate() { *x = (i as i64 * 7 + 3) % 11 - 5; }
        kv[4] = 1;
        for (v, f) in &s { kv[*v] = f.lin.iter().fold(f.c0, |a, &(w, c)| a + c * kv[w as usize]); }
        for e in [&e1, &e2] { assert_eq!(e.lin.iter().fold(e.c0, |a, &(w, c)| a + c * kv[w as usize]), 0); }
        assert!(solve_case(&[parse_affine(b"2*n0-3*n1").unwrap()], &[None; 20]).is_err());
        assert!(solve_case(&[parse_affine(b"1").unwrap()], &[None; 20]).is_err());
    }
    #[test]
    fn primes_lie_in_the_lane_window() {
        for w in [0u64, u64::MAX, 0x1234_5678_9abc_def0] {
            let c = prime_candidate(w);
            assert!(c >= 7u64 << 60 && c < (7u64 << 60) + (1u64 << 59) && c & 1 == 1);
        }
    }
}
